/// U/D/A/f Model: Explicit implementation of the theoretical foundation of specORACLE
///
/// Based on conversation.md and motivation.md:
/// - U (Universe): The space in which specifications are defined
/// - D (Domain): The region that specifications actually cover
/// - A (Admissible set): The set of allowed implementations
/// - f (Transform function): Mappings between universes
///
/// Critical insight: U0 is NOT directly written by users.
/// U0 = f₀₁⁻¹(U1) ∪ f₀₂⁻¹(U2) ∪ ... ∪ f₀ₙ⁻¹(UN)
///
/// Users write U1-UN (various specifications), and specORACLE constructs U0
/// from the inverse mappings of all layers.

mod ids;
mod metadata;
mod refs;

// Re-export type-safe ID types
pub use ids::{UniverseId, DomainId, SpecId, TransformId, IdError};
// Re-export metadata types
pub use metadata::{MetadataKey, Metadata, UniverseMetadata, DomainMetadata, ConstraintMetadata, TransformMetadata};
// Re-export reference set types
pub use refs::{SpecSet, DomainSet};

use serde::{Deserialize, Serialize};
use std::collections::{HashMap, HashSet};

/// Universe: The space in which specifications are defined
///
/// A universe represents a complete space of possible specifications at a
/// particular level of formality or abstraction.
///
/// - U0: Root specification (constructed from inverse mappings, not written directly)
/// - U1-UN: Projection universes (written by users, e.g., natural language, TLA+, code)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Universe {
    /// Unique identifier for this universe (e.g., "U0", "U1", "U2")
    pub id: UniverseId,

    /// Human-readable name (e.g., "Natural Language Requirements", "TLA+ Formal Spec", "Rust Implementation")
    pub name: String,

    /// Description of what this universe represents
    pub description: String,

    /// Specifications that belong to this universe
    pub specifications: SpecSet,

    /// Metadata for extensibility
    pub metadata: UniverseMetadata,
}

impl Universe {
    /// Create U0 (root universe) - constructed from inverse mappings
    pub fn root() -> Self {
        Self {
            id: UniverseId::root(),
            name: "Root Specification".to_string(),
            description: "The foundational universe constructed from inverse mappings of all projection universes. This represents the 'rough projection of the undefinable root specification'.".to_string(),
            specifications: SpecSet::new(),
            metadata: UniverseMetadata::new(),
        }
    }

    /// Create a projection universe (U1-UN)
    ///
    /// Returns Err if layer is 0 (use root() instead)
    pub fn projection(layer: u8, name: String, description: String) -> Result<Self, IdError> {
        let id = UniverseId::projection(layer)?;
        Ok(Self {
            id,
            name,
            description,
            specifications: SpecSet::new(),
            metadata: UniverseMetadata::new(),
        })
    }

    /// Get the layer number from the universe ID
    pub fn layer(&self) -> u8 {
        self.id.layer()
    }
}

/// Domain: The region that a specification actually covers
///
/// D represents "what this specification is about" - the subset of the universe
/// that the specification intends to govern.
///
/// Gap detection: D \ D_S (intended domain minus actually specified domain)
///
/// ## 3-Layer Structure (Phase A: Minimization)
/// - Layer 1: Identifier (`id`)
/// - Layer 2: Proof Data (`proof_data`) - formal domain boundaries, coverage tracking
/// - Layer 3: Metadata (`meta`) - human-readable info, organizational structure
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Domain {
    /// Layer 1: Unique identifier for this domain
    pub id: DomainId,

    // OLD FIELDS (deprecated, for migration compatibility)
    /// Human-readable name (DEPRECATED: use meta.name)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,

    /// What this domain covers (DEPRECATED: use meta.description)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    /// The universe this domain belongs to (DEPRECATED: use meta.universe_id)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub universe_id: Option<UniverseId>,

    /// Specifications that cover this domain (DEPRECATED: use proof_data.covered_by)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub covered_by: Option<SpecSet>,

    /// Sub-domains (DEPRECATED: use meta.subdomains)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub subdomains: Option<DomainSet>,

    /// Metadata for extensibility (DEPRECATED: use meta)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub metadata: Option<DomainMetadata>,

    // NEW FIELDS (preferred)
    /// Layer 2: Proof-essential data (constraints, coverage)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub proof_data: Option<DomainProofData>,

    /// Layer 3: Metadata (name, description, organizational structure)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub meta: Option<DomainMetadata>,
}

/// Layer 2: Proof-essential data for Domain
///
/// Contains only the data needed for formal verification and proofs.
/// The Prover should only access this layer, never metadata.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DomainProofData {
    /// Formal domain boundary constraints (NEW: for completeness proofs)
    /// When empty: Domain is not formalized (graceful degradation)
    /// When present: Enables formal proofs about domain coverage (D ⊆ D_S)
    pub constraints: Vec<Constraint>,

    /// Specifications that cover this domain (for completeness checking)
    pub covered_by: SpecSet,
}

impl DomainProofData {
    pub fn new() -> Self {
        Self {
            constraints: Vec::new(),
            covered_by: SpecSet::new(),
        }
    }

    /// Add a formal constraint to the domain boundary
    pub fn add_constraint(&mut self, constraint: Constraint) {
        self.constraints.push(constraint);
    }

    /// Check if domain is formalized (has constraints)
    pub fn is_formalized(&self) -> bool {
        !self.constraints.is_empty()
    }
}

impl Default for DomainProofData {
    fn default() -> Self {
        Self::new()
    }
}

impl Domain {
    /// Create a new domain with generated ID (NEW: uses 3-layer structure)
    pub fn new(name: String, description: String, universe_id: UniverseId) -> Self {
        let mut meta = DomainMetadata::new();
        meta.insert(MetadataKey::Custom("name".to_string()), name.clone());
        meta.insert(MetadataKey::Custom("description".to_string()), description.clone());
        meta.insert(MetadataKey::Custom("universe_id".to_string()), universe_id.as_str().to_string());

        Self {
            id: DomainId::new(),
            // OLD fields (populated for compatibility)
            name: Some(name),
            description: Some(description),
            universe_id: Some(universe_id),
            covered_by: Some(SpecSet::new()),
            subdomains: Some(DomainSet::new()),
            metadata: Some(DomainMetadata::new()),
            // NEW fields (preferred)
            proof_data: Some(DomainProofData::new()),
            meta: Some(meta),
        }
    }

    /// Create a domain with specific ID (for loading from storage)
    pub fn with_id(id: DomainId, name: String, description: String, universe_id: UniverseId) -> Self {
        let mut meta = DomainMetadata::new();
        meta.insert(MetadataKey::Custom("name".to_string()), name.clone());
        meta.insert(MetadataKey::Custom("description".to_string()), description.clone());
        meta.insert(MetadataKey::Custom("universe_id".to_string()), universe_id.as_str().to_string());

        Self {
            id,
            // OLD fields (populated for compatibility)
            name: Some(name),
            description: Some(description),
            universe_id: Some(universe_id),
            covered_by: Some(SpecSet::new()),
            subdomains: Some(DomainSet::new()),
            metadata: Some(DomainMetadata::new()),
            // NEW fields (preferred)
            proof_data: Some(DomainProofData::new()),
            meta: Some(meta),
        }
    }

    /// Add a formal constraint to the domain boundary
    pub fn add_constraint(&mut self, constraint: Constraint) {
        if let Some(proof_data) = &mut self.proof_data {
            proof_data.add_constraint(constraint);
        }
    }

    /// Get proof data (for Prover access)
    pub fn get_proof_data(&self) -> Option<&DomainProofData> {
        self.proof_data.as_ref()
    }

    /// Get mutable proof data
    pub fn get_proof_data_mut(&mut self) -> Option<&mut DomainProofData> {
        self.proof_data.as_mut()
    }

    /// Check if this domain has any coverage gaps
    /// Tries new field first, falls back to old field
    pub fn has_gaps(&self) -> bool {
        if let Some(proof_data) = &self.proof_data {
            proof_data.covered_by.is_empty()
        } else if let Some(covered_by) = &self.covered_by {
            covered_by.is_empty()
        } else {
            true
        }
    }
}

/// Admissible Set: The set of implementations allowed by a specification
///
/// A represents "what is correct" - all implementations that satisfy the specification.
/// Contradiction detection: A1 ∩ A2 = ∅ (disjoint admissible sets)
///
/// Note: This is a symbolic representation. The actual admissible set is infinite
/// and cannot be enumerated. Instead, we represent it through constraints.
///
/// ## 3-Layer Structure (Phase A: Minimization)
/// - Layer 1: Identifier (`id`)
/// - Layer 2: Proof Data (`proof_data`) - constraints, contradictions
/// - Layer 3: Metadata (`meta`) - organizational info
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AdmissibleSet {
    /// Layer 1: The specification that defines this admissible set
    pub spec_id: SpecId,

    // OLD FIELDS (deprecated, for migration compatibility)
    /// The universe this admissible set belongs to (DEPRECATED: use meta.universe_id)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub universe_id: Option<UniverseId>,

    /// Constraints that define membership (DEPRECATED: use proof_data.constraints)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub constraints: Option<Vec<Constraint>>,

    /// Known contradictions (DEPRECATED: use proof_data.contradicts)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub contradicts: Option<SpecSet>,

    /// Metadata for extensibility (DEPRECATED: use meta)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub metadata: Option<Metadata>,

    // NEW FIELDS (preferred)
    /// Layer 2: Proof-essential data (constraints, contradictions)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub proof_data: Option<AdmissibleSetProofData>,

    /// Layer 3: Metadata (organizational info)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub meta: Option<AdmissibleSetMetadata>,
}

/// Layer 2: Proof-essential data for AdmissibleSet
///
/// Contains only the data needed for formal verification and proofs.
/// The Prover should only access this layer, never metadata.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AdmissibleSetProofData {
    /// Constraints that define membership in this set
    pub constraints: Vec<Constraint>,

    /// Pre-marked contradictions with other admissible sets
    pub contradicts: SpecSet,
}

/// Layer 3: Metadata for AdmissibleSet
///
/// Contains human-readable and organizational information.
/// NOT used in formal proofs.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AdmissibleSetMetadata {
    /// The universe this admissible set belongs to (organizational)
    pub universe_id: UniverseId,

    /// Extensible metadata
    #[serde(flatten)]
    pub extra: HashMap<String, String>,
}

impl AdmissibleSetProofData {
    pub fn new() -> Self {
        Self {
            constraints: Vec::new(),
            contradicts: SpecSet::new(),
        }
    }

    /// Add a constraint to this admissible set
    pub fn add_constraint(&mut self, constraint: Constraint) {
        self.constraints.push(constraint);
    }

    /// Mark this admissible set as contradicting another
    pub fn mark_contradiction(&mut self, other_id: SpecId) {
        self.contradicts.insert(other_id);
    }
}

impl Default for AdmissibleSetProofData {
    fn default() -> Self {
        Self::new()
    }
}

impl AdmissibleSetMetadata {
    pub fn new(universe_id: UniverseId) -> Self {
        Self {
            universe_id,
            extra: HashMap::new(),
        }
    }
}

impl AdmissibleSet {
    pub fn new(spec_id: SpecId, universe_id: UniverseId) -> Self {
        Self {
            spec_id,
            // OLD fields (populated for compatibility)
            universe_id: Some(universe_id.clone()),
            constraints: Some(Vec::new()),
            contradicts: Some(SpecSet::new()),
            metadata: Some(Metadata::new()),
            // NEW fields (preferred)
            proof_data: Some(AdmissibleSetProofData::new()),
            meta: Some(AdmissibleSetMetadata::new(universe_id)),
        }
    }

    /// Add a constraint to this admissible set
    pub fn add_constraint(&mut self, constraint: Constraint) {
        // Update both old and new fields during migration
        if let Some(constraints) = &mut self.constraints {
            constraints.push(constraint.clone());
        }
        if let Some(proof_data) = &mut self.proof_data {
            proof_data.add_constraint(constraint);
        }
    }

    /// Mark this admissible set as contradicting another
    pub fn mark_contradiction(&mut self, other_id: SpecId) {
        // Update both old and new fields during migration
        if let Some(contradicts) = &mut self.contradicts {
            contradicts.insert(other_id.clone());
        }
        if let Some(proof_data) = &mut self.proof_data {
            proof_data.mark_contradiction(other_id);
        }
    }

    /// Get proof data (for Prover access)
