    fn prove_satisfiability_consistent_constraints() {
        let mut prover = Prover::new();
        let mut spec = AdmissibleSet::new(crate::SpecId::new(), crate::UniverseId::root());

        let mut meta1 = crate::ConstraintMetadata::new();
        meta1.insert(crate::MetadataKey::Custom("description".to_string()),
                     "x must be at least 5".to_string());

        spec.add_constraint(Constraint {
            formal: None,
            kind: ConstraintKind::Universal,
            description: Some("x must be at least 5".to_string()),
            metadata: Some(crate::ConstraintMetadata::new()),
            meta: Some(meta1),
        });

        let mut meta2 = crate::ConstraintMetadata::new();
        meta2.insert(crate::MetadataKey::Custom("description".to_string()),
                     "x must be at most 10".to_string());

        spec.add_constraint(Constraint {
            formal: None,
            kind: ConstraintKind::Universal,
            description: Some("x must be at most 10".to_string()),
            metadata: Some(crate::ConstraintMetadata::new()),
            meta: Some(meta2),
        });

        let proof = prover.prove_satisfiability(&spec);

        // Should be Unknown (not Refuted) because constraints are compatible
        assert_ne!(proof.status, ProofStatus::Refuted);
    }

    #[test]
    fn prove_satisfiability_conflicting_constraints() {
        let mut prover = Prover::new();
        let mut spec = AdmissibleSet::new(crate::SpecId::new(), crate::UniverseId::root());

        spec.add_constraint(Constraint {
            description: "x must be at least 10".to_string(),
            formal: None,
            kind: ConstraintKind::Universal,
            metadata: crate::ConstraintMetadata::new(),
        });

        spec.add_constraint(Constraint {
            description: "x must be at most 5".to_string(),
            formal: None,
            kind: ConstraintKind::Universal,
            metadata: crate::ConstraintMetadata::new(),
        });

        let proof = prover.prove_satisfiability(&spec);

        assert_eq!(proof.status, ProofStatus::Refuted);
        assert!(proof.steps.iter().any(|s|
            s.description.contains("unsatisfiability") ||
            s.description.contains("UNSATISFIABLE")));
    }

