        let proof = prover.prove_satisfiability(&spec);

        #[cfg(feature = "z3-solver")]
        {
            assert_eq!(proof.status, ProofStatus::Refuted);
            assert!(proof.steps.iter().any(|s|
                s.description.contains("unsatisfiability") ||
                s.description.contains("UNSATISFIABLE")));
        }

        #[cfg(not(feature = "z3-solver"))]
        {
            assert_eq!(proof.status, ProofStatus::Unknown);
        }
    }

    #[test]
    fn prove_consistency_compatible_specs() {
        let mut prover = Prover::new();

        let mut spec_a = AdmissibleSet::new(crate::SpecId::new(), crate::UniverseId::root());

        let mut meta_a = crate::ConstraintMetadata::new();
        meta_a.insert(crate::MetadataKey::Custom("description".to_string()),
                     "password must be at least 8 characters".to_string());

        spec_a.add_constraint(Constraint {
            formal: None,
            kind: ConstraintKind::Universal,
            description: Some("password must be at least 8 characters".to_string()),
            metadata: Some(crate::ConstraintMetadata::new()),
            meta: Some(meta_a),
        });

        let mut spec_b = AdmissibleSet::new(crate::SpecId::new(), crate::UniverseId::root());

        let mut meta_b = crate::ConstraintMetadata::new();
        meta_b.insert(crate::MetadataKey::Custom("description".to_string()),
                     "password must be at most 20 characters".to_string());

        spec_b.add_constraint(Constraint {
            formal: None,
            kind: ConstraintKind::Universal,
            description: Some("password must be at most 20 characters".to_string()),
            metadata: Some(crate::ConstraintMetadata::new()),
            meta: Some(meta_b),
        });

        let proof = prover.prove_consistency(&spec_a, &spec_b);

        // Should be Unknown (not Refuted) because specs are compatible
        assert_ne!(proof.status, ProofStatus::Refuted);
    }

    #[test]
    fn prove_consistency_conflicting_specs() {
        let mut prover = Prover::new();

        let mut spec_a = AdmissibleSet::new(crate::SpecId::new(), crate::UniverseId::root());

        let mut meta_a = crate::ConstraintMetadata::new();
        meta_a.insert(crate::MetadataKey::Custom("description".to_string()),
                     "password must be at least 10 characters".to_string());

        spec_a.add_constraint(Constraint {
            formal: None,
            kind: ConstraintKind::Universal,
            description: Some("password must be at least 10 characters".to_string()),
            metadata: Some(crate::ConstraintMetadata::new()),
            meta: Some(meta_a),
        });

        let mut spec_b = AdmissibleSet::new(crate::SpecId::new(), crate::UniverseId::root());

        let mut meta_b = crate::ConstraintMetadata::new();
        meta_b.insert(crate::MetadataKey::Custom("description".to_string()),
                     "password must be at most 8 characters".to_string());

        spec_b.add_constraint(Constraint {
            formal: None,
            kind: ConstraintKind::Universal,
            description: Some("password must be at most 8 characters".to_string()),
            metadata: Some(crate::ConstraintMetadata::new()),
            meta: Some(meta_b),
        });

        let proof = prover.prove_consistency(&spec_a, &spec_b);

        #[cfg(feature = "z3-solver")]
        {
            assert_eq!(proof.status, ProofStatus::Refuted);
            assert!(proof.steps.iter().any(|s|
                s.description.contains("contradiction") ||
                s.description.contains("CONTRADICTORY")));
        }

        #[cfg(not(feature = "z3-solver"))]
        {
            assert_eq!(proof.status, ProofStatus::Unknown);
        }
    }

    #[test]
    fn list_proofs_for_spec() {
        let mut prover = Prover::new();
        let spec_a = AdmissibleSet::new(crate::SpecId::new(), crate::UniverseId::root());
        let spec_b = AdmissibleSet::new(crate::SpecId::new(), crate::UniverseId::root());
        let spec_c = AdmissibleSet::new(crate::SpecId::new(), crate::UniverseId::root());

        prover.prove_satisfiability(&spec_a);
        prover.prove_consistency(&spec_a, &spec_b);
        prover.prove_satisfiability(&spec_c);

        let proofs_for_a = prover.get_proofs_for_spec(spec_a.spec_id.as_str());
        assert_eq!(proofs_for_a.len(), 2); // satisfiability + consistency

        let proofs_for_c = prover.get_proofs_for_spec(spec_c.spec_id.as_str());
        assert_eq!(proofs_for_c.len(), 1); // only satisfiability
    }
}

