        let constraints_a = vec![
            Constraint {
                formal: None,
                kind: ConstraintKind::Universal,
                description: Some("password must be at least 20 characters".to_string()),
                metadata: Some(crate::ConstraintMetadata::new()),
                meta: Some(meta_a),
            },
        ];
        let constraints_b = vec![
