   156→    fn check_satisfiability_z3(
   157→        &self,
   158→        constraints: &[Constraint],
   159→    ) -> (ProofStatus, Vec<ProofStep>) {
   160→        let mut steps = Vec::new();
   161→
   162→        if constraints.is_empty() {
   163→            steps.push(ProofStep {
   164→                description: "No constraints - trivially satisfiable".to_string(),
   165→                justification: "Empty constraint set".to_string(),
   166→            });
   167→            return (ProofStatus::Proven, steps);
   168→        }
   169→
   170→        steps.push(ProofStep {
   171→            description: format!("Encoding {} constraints into Z3", constraints.len()),
   172→            justification: "SMT encoding".to_string(),
   173→        });
   174→
   175→        let solver = Solver::new(&self.context);
   176→        let mut var_map: HashMap<String, Int<'_>> = HashMap::new();
   177→
   178→        // Encode constraints into Z3
   179→        for constraint in constraints {
   180→            // Extract description for encoding (try new structure first, fallback to old)
   181→            let desc = if let Some(meta) = &constraint.meta {
   182→                meta.get_str("description").map(|s| s.as_str())
   183→            } else {
   184→                constraint.description.as_deref()
   185→            }.unwrap_or("");
   186→
   187→            if let Some(assertion) = self.encode_constraint(desc, &mut var_map) {
   188→                solver.assert(&assertion);
   189→                steps.push(ProofStep {
   190→                    description: format!("Encoded: {}", desc),
   191→                    justification: "Constraint encoding".to_string(),
   192→                });
   193→            }
   194→        }
   195→
   196→        steps.push(ProofStep {
   197→            description: "Invoking Z3 solver".to_string(),
   198→            justification: "SMT solving".to_string(),
   199→        });
   200→
   201→        // Check satisfiability
   202→        match solver.check() {
   203→            z3::SatResult::Sat => {
   204→                steps.push(ProofStep {
   205→                    description: "Z3 proved: SATISFIABLE (model exists)".to_string(),
   206→                    justification: "SMT solver verdict".to_string(),
   207→                });
   208→
   209→                // Get model for witness
   210→                if let Some(model) = solver.get_model() {
   211→                    let witness = format!("Witness: {}", model);
   212→                    steps.push(ProofStep {
   213→                        description: witness,
   214→                        justification: "Model extraction".to_string(),
   215→                    });
   216→                }
   217→
   218→                (ProofStatus::Proven, steps)
   219→            }
   220→            z3::SatResult::Unsat => {
   221→                steps.push(ProofStep {
   222→                    description: "Z3 proved: UNSATISFIABLE (no solution exists)".to_string(),
   223→                    justification: "SMT solver verdict".to_string(),
   224→                });
   225→
   226→                // Get unsat core for explanation
   227→                let core = solver.get_unsat_core();
   228→                if !core.is_empty() {
   229→                    let core_desc = format!("Unsat core: {} constraints conflict", core.len());
   230→                    steps.push(ProofStep {
   231→                        description: core_desc,
   232→                        justification: "Unsat core extraction".to_string(),
   233→                    });
   234→                }
   235→
   236→                (ProofStatus::Refuted, steps)
   237→            }
   238→            z3::SatResult::Unknown => {
   239→                steps.push(ProofStep {
   240→                    description: "Z3 returned: UNKNOWN (timeout or incomplete)".to_string(),
   241→                    justification: "SMT solver limitation".to_string(),
   242→                });
   243→                (ProofStatus::Unknown, steps)
   244→            }
   245→        }
   246→    }
