   362→            justification: "Completeness problem setup".to_string(),
   363→        });
   364→
   365→        steps.push(ProofStep {
   366→            description: "Formula: UNSAT(D ∧ ¬A1 ∧ ¬A2 ∧ ... ∧ ¬An)".to_string(),
   367→            justification: "Completeness encoding".to_string(),
   368→        });
   369→
   370→        let solver = Solver::new(&self.context);
   371→        let mut var_map: HashMap<String, Int<'_>> = HashMap::new();
   372→
   373→        // Encode domain constraints
   374→        let mut encoded_d = 0;
