   376→            let desc = if let Some(meta) = &constraint.meta {
   377→                meta.get_str("description").map(|s| s.as_str())
   378→            } else {
   379→                constraint.description.as_deref()
   380→            }.unwrap_or("");
   381→
   382→            if let Some(assertion) = self.encode_constraint(desc, &mut var_map) {
   383→                solver.assert(&assertion);
   384→                encoded_d += 1;
   385→            }
   386→        }
   387→
   388→        // Encode ¬(A1 ∨ A2 ∨ ... ∨ An) = ¬A1 ∧ ¬A2 ∧ ... ∧ ¬An
   389→        let mut encoded_specs = 0;
   390→        for constraints in spec_constraints {
   391→            // For each spec, we need to negate ALL its constraints
   392→            // ¬Ai = ¬(c1 ∧ c2 ∧ ... ∧ cn) = ¬c1 ∨ ¬c2 ∨ ... ∨ ¬cn
   393→            // But we need ¬A1 ∧ ¬A2, so we negate each spec as a whole
   394→
   395→            let mut spec_assertions = Vec::new();
   396→            for constraint in *constraints {
   397→                let desc = if let Some(meta) = &constraint.meta {
   398→                    meta.get_str("description").map(|s| s.as_str())
   399→                } else {
   400→                    constraint.description.as_deref()
   401→                }.unwrap_or("");
   402→
   403→                if let Some(assertion) = self.encode_constraint(desc, &mut var_map) {
   404→                    spec_assertions.push(assertion);
   405→                }
   406→            }
