   471→    #[cfg(feature = "z3-solver")]
   472→    fn check_consistency_within_domain_z3(
   473→        &self,
   474→        constraints_a: &[Constraint],
   475→        constraints_b: &[Constraint],
   476→        domain_constraints: &[Constraint],
   477→    ) -> (ProofStatus, Vec<ProofStep>) {
   478→        let mut steps = Vec::new();
   479→
   480→        steps.push(ProofStep {
   481→            description: format!(
   482→                "Checking consistency within domain: {} constraints (A) ∩ {} constraints (B) ∩ {} constraints (D)",
   483→                constraints_a.len(),
   484→                constraints_b.len(),
   485→                domain_constraints.len()
   486→            ),
   487→            justification: "Consistency within domain setup".to_string(),
   488→        });
   489→
   490→        let solver = Solver::new(&self.context);
   491→        let mut var_map: HashMap<String, Int<'_>> = HashMap::new();
   492→
   493→        // Encode constraints from A1
   494→        let mut encoded_a = 0;
   495→        for constraint in constraints_a {
   496→            let desc = if let Some(meta) = &constraint.meta {
   497→                meta.get_str("description").map(|s| s.as_str())
   498→            } else {
   499→                constraint.description.as_deref()
   500→            }.unwrap_or("");
   501→
   502→            if let Some(assertion) = self.encode_constraint(desc, &mut var_map) {
   503→                solver.assert(&assertion);
   504→                encoded_a += 1;
   505→            }
   506→        }
   507→
   508→        // Encode constraints from A2
   509→        let mut encoded_b = 0;
   510→        for constraint in constraints_b {
   511→            let desc = if let Some(meta) = &constraint.meta {
   512→                meta.get_str("description").map(|s| s.as_str())
   513→            } else {
   514→                constraint.description.as_deref()
   515→            }.unwrap_or("");
   516→
   517→            if let Some(assertion) = self.encode_constraint(desc, &mut var_map) {
   518→                solver.assert(&assertion);
   519→                encoded_b += 1;
   520→            }
   521→        }
   522→
   523→        // Encode domain constraints
   524→        let mut encoded_d = 0;
   525→        for constraint in domain_constraints {
   526→            let desc = if let Some(meta) = &constraint.meta {
   527→                meta.get_str("description").map(|s| s.as_str())
   528→            } else {
   529→                constraint.description.as_deref()
   530→            }.unwrap_or("");
   531→
   532→            if let Some(assertion) = self.encode_constraint(desc, &mut var_map) {
   533→                solver.assert(&assertion);
   534→                encoded_d += 1;
   535→            }
   536→        }
   537→
   538→        steps.push(ProofStep {
   539→            description: format!(
   540→                "Encoded {} from A, {} from B, {} from D",
   541→                encoded_a, encoded_b, encoded_d
   542→            ),
   543→            justification: "SMT encoding".to_string(),
   544→        });
   545→
   546→        steps.push(ProofStep {
   547→            description: "Invoking Z3 to check consistency within domain".to_string(),
   548→            justification: "SMT solving".to_string(),
   549→        });
   550→
   551→        // If SAT, then consistent within domain (A ∩ B ∩ D ≠ ∅)
   552→        // If UNSAT, then contradictory within domain (A ∩ B ∩ D = ∅)
   553→        match solver.check() {
   554→            z3::SatResult::Sat => {
   555→                steps.push(ProofStep {
   556→                    description: "Z3 proved: CONSISTENT within domain (A ∩ B ∩ D ≠ ∅)".to_string(),
   557→                    justification: "SMT solver verdict".to_string(),
   558→                });
   559→
   560→                if let Some(model) = solver.get_model() {
   561→                    steps.push(ProofStep {
   562→                        description: format!("Witness exists: {}", model),
   563→                        justification: "Model extraction".to_string(),
   564→                    });
   565→                }
   566→
   567→                (ProofStatus::Proven, steps)
   568→            }
   569→            z3::SatResult::Unsat => {
   570→                steps.push(ProofStep {
   571→                    description: "Z3 proved: CONTRADICTORY within domain (A ∩ B ∩ D = ∅)".to_string(),
   572→                    justification: "SMT solver verdict".to_string(),
   573→                });
   574→                (ProofStatus::Refuted, steps)
   575→            }
   576→            z3::SatResult::Unknown => {
   577→                steps.push(ProofStep {
   578→                    description: "Z3 returned: UNKNOWN".to_string(),
   579→                    justification: "SMT solver limitation".to_string(),
   580→                });
   581→                (ProofStatus::Unknown, steps)
   582→            }
   583→        }
   584→    }
