   586→    #[cfg(feature = "z3-solver")]
   587→    fn check_implication_z3(
   588→        &self,
   589→        constraints_antecedent: &[Constraint],
   590→        constraints_consequent: &[Constraint],
   591→    ) -> (ProofStatus, Vec<ProofStep>) {
   592→        let mut steps = Vec::new();
   593→
   594→        steps.push(ProofStep {
   595→            description: format!(
   596→                "Checking implication: A1({} constraints) ⊆ A2({} constraints)",
   597→                constraints_antecedent.len(),
   598→                constraints_consequent.len()
   599→            ),
   600→            justification: "Implication problem setup".to_string(),
   601→        });
   602→
   603→        steps.push(ProofStep {
   604→            description: "Formula: UNSAT(A1 ∧ ¬A2)".to_string(),
   605→            justification: "Implication encoding".to_string(),
   606→        });
   607→
   608→        let solver = Solver::new(&self.context);
   609→        let mut var_map: HashMap<String, Int<'_>> = HashMap::new();
   610→
   611→        // Encode antecedent (A1)
   612→        let mut encoded_a1 = 0;
   613→        for constraint in constraints_antecedent {
   614→            let desc = if let Some(meta) = &constraint.meta {
   615→                meta.get_str("description").map(|s| s.as_str())
   616→            } else {
   617→                constraint.description.as_deref()
   618→            }.unwrap_or("");
   619→
   620→            if let Some(assertion) = self.encode_constraint(desc, &mut var_map) {
   621→                solver.assert(&assertion);
   622→                encoded_a1 += 1;
   623→            }
   624→        }
   625→
   626→        // Encode ¬A2 (negation of consequent)
   627→        let mut encoded_not_a2 = 0;
   628→        for constraint in constraints_consequent {
   629→            let desc = if let Some(meta) = &constraint.meta {
   630→                meta.get_str("description").map(|s| s.as_str())
   631→            } else {
   632→                constraint.description.as_deref()
   633→            }.unwrap_or("");
   634→
   635→            if let Some(assertion) = self.encode_constraint(desc, &mut var_map) {
   636→                // Negate the assertion
   637→                solver.assert(&assertion.not());
   638→                encoded_not_a2 += 1;
   639→            }
   640→        }
   641→
   642→        steps.push(ProofStep {
   643→            description: format!(
   644→                "Encoded {} constraints from A1, {} negated constraints from A2",
   645→                encoded_a1, encoded_not_a2
   646→            ),
   647→            justification: "SMT encoding".to_string(),
   648→        });
   649→
   650→        steps.push(ProofStep {
   651→            description: "Invoking Z3 to check implication".to_string(),
   652→            justification: "SMT solving".to_string(),
   653→        });
   654→
   655→        // If UNSAT, then A1 ⊆ A2 (implication holds)
   656→        // If SAT, then there exists x ∈ A1 but x ∉ A2 (counterexample)
   657→        match solver.check() {
   658→            z3::SatResult::Unsat => {
   659→                steps.push(ProofStep {
   660→                    description: "Z3 proved: UNSAT(A1 ∧ ¬A2) → A1 ⊆ A2 (implication holds)".to_string(),
   661→                    justification: "SMT solver verdict".to_string(),
   662→                });
   663→                (ProofStatus::Proven, steps)
   664→            }
   665→            z3::SatResult::Sat => {
   666→                steps.push(ProofStep {
   667→                    description: "Z3 proved: SAT(A1 ∧ ¬A2) → Counterexample exists (implication does NOT hold)".to_string(),
   668→                    justification: "SMT solver verdict".to_string(),
   669→                });
   670→
   671→                if let Some(model) = solver.get_model() {
   672→                    steps.push(ProofStep {
   673→                        description: format!("Counterexample: {}", model),
   674→                        justification: "Model extraction".to_string(),
   675→                    });
   676→                }
   677→
   678→                (ProofStatus::Refuted, steps)
   679→            }
   680→            z3::SatResult::Unknown => {
   681→                steps.push(ProofStep {
   682→                    description: "Z3 returned: UNKNOWN".to_string(),
   683→                    justification: "SMT solver limitation".to_string(),
   684→                });
   685→                (ProofStatus::Unknown, steps)
   686→            }
   687→        }
   688→    }
