   690→    #[cfg(feature = "z3-solver")]
   691→    fn encode_constraint<'ctx>(
   692→        &'ctx self,
   693→        description: &str,
   694→        var_map: &mut HashMap<String, Int<'ctx>>,
   695→    ) -> Option<Bool<'ctx>> {
   696→        let desc_lower = description.to_lowercase();
   697→
   698→        // Extract variable name (heuristic: first word before "must")
   699→        let var_name = self.extract_variable_name(&desc_lower).unwrap_or_else(|| "x".to_string());
   700→
   701→        // Get or create variable
   702→        let var = if let Some(existing) = var_map.get(&var_name) {
   703→            existing.clone()
   704→        } else {
   705→            let new_var = Int::new_const(&self.context, var_name.as_str());
   706→            var_map.insert(var_name.clone(), new_var.clone());
   707→            new_var
   708→        };
   709→
   710→        // Pattern matching for constraint types
   711→        if let Some(min) = self.extract_minimum(&desc_lower) {
   712→            // "at least N", "minimum N", ">= N"
   713→            let n = Int::from_i64(&self.context, min);
   714→            return Some(var.ge(&n));
   715→        }
   716→
   717→        if let Some(max) = self.extract_maximum(&desc_lower) {
   718→            // "at most N", "maximum N", "<= N"
   719→            let n = Int::from_i64(&self.context, max);
   720→            return Some(var.le(&n));
   721→        }
   722→
   723→        if let Some(exact) = self.extract_exact(&desc_lower) {
   724→            // "exactly N", "must be N"
   725→            let n = Int::from_i64(&self.context, exact);
   726→            return Some(var._eq(&n));
   727→        }
   728→
   729→        if let Some((min, max)) = self.extract_range(&desc_lower) {
   730→            // "between X and Y"
   731→            let min_val = Int::from_i64(&self.context, min);
   732→            let max_val = Int::from_i64(&self.context, max);
   733→            let ge = var.ge(&min_val);
   734→            let le = var.le(&max_val);
   735→            return Some(Bool::and(&self.context, &[&ge, &le]));
   736→        }
   737→
   738→        // Unable to encode this constraint
   739→        None
   740→    }
