   742→    #[cfg(feature = "z3-solver")]
   743→    fn extract_variable_name(&self, desc: &str) -> Option<String> {
   744→        // Extract variable name from patterns like "password must be..."
   745→        let words: Vec<&str> = desc.split_whitespace().collect();
   746→        if let Some(pos) = words.iter().position(|&w| w == "must" || w == "should") {
   747→            if pos > 0 {
   748→                return Some(words[pos - 1].to_string());
   749→            }
   750→        }
   751→        None
   752→    }
   753→
   754→    fn extract_minimum(&self, desc: &str) -> Option<i64> {
   755→        if let Some(pos) = desc.find("at least") {
   756→            return self.extract_number(&desc[pos..]);
   757→        }
   758→        if let Some(pos) = desc.find("minimum") {
   759→            return self.extract_number(&desc[pos..]);
   760→        }
   761→        if let Some(pos) = desc.find(">=") {
   762→            return self.extract_number(&desc[pos..]);
   763→        }
   764→        None
   765→    }
   766→
   767→    fn extract_maximum(&self, desc: &str) -> Option<i64> {
   768→        if let Some(pos) = desc.find("at most") {
   769→            return self.extract_number(&desc[pos..]);
   770→        }
   771→        if let Some(pos) = desc.find("maximum") {
   772→            return self.extract_number(&desc[pos..]);
   773→        }
   774→        if let Some(pos) = desc.find("<=") {
   775→            return self.extract_number(&desc[pos..]);
   776→        }
   777→        None
   778→    }
   779→
   780→    fn extract_exact(&self, desc: &str) -> Option<i64> {
   781→        if let Some(pos) = desc.find("exactly") {
   782→            return self.extract_number(&desc[pos..]);
   783→        }
   784→        if desc.contains("must be") && !desc.contains("at least") && !desc.contains("at most") {
   785→            return self.extract_number(desc);
   786→        }
   787→        None
   788→    }
   789→
   790→    fn extract_range(&self, desc: &str) -> Option<(i64, i64)> {
   791→        if let Some(pos) = desc.find("between") {
   792→            let rest = &desc[pos..];
   793→            let numbers: Vec<i64> = rest.split_whitespace()
   794→                .filter_map(|w| w.trim_matches(|c: char| !c.is_numeric()).parse::<i64>().ok())
   795→                .collect();
   796→            if numbers.len() >= 2 {
   797→                return Some((numbers[0], numbers[1]));
   798→            }
   799→        }
   800→        None
   801→    }
   802→
   803→    fn extract_number(&self, s: &str) -> Option<i64> {
   804→        for word in s.split_whitespace() {
   805→            if let Ok(n) = word.trim_matches(|c: char| !c.is_numeric()).parse::<i64>() {
   806→                return Some(n);
   807→            }
   808→        }
   809→        None
   810→    }
   811→}
