     1→/// Type-safe ID system for UDAF model
     2→///
     3→/// This module provides strongly-typed identifiers for Universe, Domain, Spec, and Transform
     4→/// to prevent type confusion and enforce naming conventions.
     5→
     6→use serde::{Deserialize, Serialize, Deserializer, Serializer};
     7→use std::fmt;
