    10→/// Error type for ID parsing and validation
    11→#[derive(Debug, Clone, PartialEq, Eq)]
    12→pub enum IdError {
    13→    InvalidFormat(String),
    14→    InvalidLayer(String),
    15→    InvalidUuid(String),
    16→}
    17→
    18→impl fmt::Display for IdError {
    19→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    20→        match self {
    21→            IdError::InvalidFormat(msg) => write!(f, "Invalid ID format: {}", msg),
    22→            IdError::InvalidLayer(msg) => write!(f, "Invalid layer: {}", msg),
    23→            IdError::InvalidUuid(msg) => write!(f, "Invalid UUID: {}", msg),
    24→        }
    25→    }
    26→}
    27→
    28→impl std::error::Error for IdError {}
    29→
    30→/// Universe identifier with enforced "U{layer}" format
    31→///
    32→/// Valid formats: "U0", "U1", "U2", etc.
    33→/// Layer must be a non-negative integer.
    34→#[derive(Debug, Clone, PartialEq, Eq, Hash)]
    35→pub struct UniverseId(String);
    36→
    37→impl UniverseId {
    38→    /// Create U0 (root universe)
    39→    pub fn root() -> Self {
    40→        Self("U0".to_string())
    41→    }
    42→
    43→    /// Create a projection universe (U1, U2, ...)
    44→    pub fn projection(layer: u8) -> Result<Self, IdError> {
    45→        if layer == 0 {
    46→            return Err(IdError::InvalidLayer(
    47→                "Use UniverseId::root() for U0".to_string(),
    48→            ));
    49→        }
    50→        Ok(Self(format!("U{}", layer)))
    51→    }
    52→
    53→    /// Parse from string, validating format
    54→    pub fn parse(s: &str) -> Result<Self, IdError> {
    55→        if !s.starts_with('U') {
    56→            return Err(IdError::InvalidFormat(
    57→                format!("Universe ID must start with 'U', got: {}", s),
    58→            ));
    59→        }
    60→
    61→        let layer_str = &s[1..];
    62→        layer_str.parse::<u8>().map_err(|_| {
    63→            IdError::InvalidFormat(format!("Invalid layer number in: {}", s))
    64→        })?;
    65→
    66→        Ok(Self(s.to_string()))
    67→    }
    68→
    69→    /// Get the layer number
    70→    pub fn layer(&self) -> u8 {
    71→        self.0[1..].parse().unwrap_or(0)
    72→    }
    73→
    74→    /// Get the string representation
    75→    pub fn as_str(&self) -> &str {
    76→        &self.0
    77→    }
    78→}
