   301→impl<'de> Deserialize<'de> for TransformId {
   302→    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
   303→    where
   304→        D: Deserializer<'de>,
   305→    {
   306→        let s = String::deserialize(deserializer)?;
