    10→/// Type-safe set of specification IDs
    11→///
    12→/// Internally stores HashSet<String> for serialization compatibility,
    13→/// but enforces type safety through the API.
    14→#[derive(Debug, Clone, PartialEq, Eq)]
    15→pub struct SpecSet {
    16→    inner: HashSet<String>,
    17→}
    18→
    19→impl SpecSet {
    20→    /// Create an empty set
    21→    pub fn new() -> Self {
    22→        Self {
    23→            inner: HashSet::new(),
    24→        }
    25→    }
    26→
    27→    /// Insert a specification ID
    28→    pub fn insert(&mut self, id: SpecId) -> bool {
    29→        self.inner.insert(id.as_str().to_string())
    30→    }
    31→
    32→    /// Insert a specification ID from string (validates format)
    33→    pub fn insert_str(&mut self, id_str: String) -> Result<bool, super::ids::IdError> {
    34→        let id = SpecId::parse(&id_str)?;
    35→        Ok(self.inner.insert(id.as_str().to_string()))
    36→    }
    37→
    38→    /// Check if set contains a specification ID
    39→    pub fn contains(&self, id: &SpecId) -> bool {
    40→        self.inner.contains(id.as_str())
    41→    }
    42→
    43→    /// Check if set contains an ID string (for compatibility)
    44→    pub fn contains_str(&self, id_str: &str) -> bool {
    45→        self.inner.contains(id_str)
    46→    }
    47→
    48→    /// Remove a specification ID
    49→    pub fn remove(&mut self, id: &SpecId) -> bool {
    50→        self.inner.remove(id.as_str())
    51→    }
    52→
    53→    /// Get the number of IDs in the set
    54→    pub fn len(&self) -> usize {
    55→        self.inner.len()
    56→    }
    57→
    58→    /// Check if the set is empty
    59→    pub fn is_empty(&self) -> bool {
    60→        self.inner.is_empty()
    61→    }
    62→
    63→    /// Iterate over IDs as strings (for compatibility)
    64→    pub fn iter_str(&self) -> impl Iterator<Item = &String> {
    65→        self.inner.iter()
    66→    }
    67→
    68→    /// Iterate over parsed SpecIds
    69→    ///
    70→    /// Note: This validates each ID during iteration. IDs that fail validation are skipped.
    71→    pub fn iter(&self) -> impl Iterator<Item = SpecId> + '_ {
    72→        self.inner.iter().filter_map(|s| SpecId::parse(s).ok())
    73→    }
    74→
    75→    /// Validate all IDs in the set
    76→    ///
    77→    /// Returns Err if any ID fails to parse as a valid SpecId.
    78→    pub fn validate(&self) -> Result<(), super::ids::IdError> {
    79→        for id_str in &self.inner {
    80→            SpecId::parse(id_str)?;
    81→        }
    82→        Ok(())
    83→    }
    84→
    85→    /// Check reference integrity: all IDs in this set exist in the given set
    86→    ///
    87→    /// Returns the list of IDs that don't exist in the reference set.
    88→    pub fn check_integrity(&self, valid_ids: &HashSet<String>) -> Vec<String> {
    89→        self.inner
    90→            .iter()
    91→            .filter(|id| !valid_ids.contains(*id))
    92→            .cloned()
    93→            .collect()
    94→    }
    95→
    96→    /// Get the inner HashSet (for direct access when needed)
    97→    pub fn inner(&self) -> &HashSet<String> {
    98→        &self.inner
    99→    }
